pub fn find_witness_realized(
    source_facts: Rc<Node>,
    candidates: Rc<CandidateSet>,
    predicate: Rc<PreservationPredicate>,
    multiplicity_policy: Rc<MultiplicityPolicy>,
) -> Rc<Outcome<Rc<FindWitnessResult>>> {
    if (preservation_rule_is_realized(predicate.preservation_rule.clone()) == false) {
        outcome_rejected(find_witness_not_realized_diagnostic(source_facts.clone()))
    } else {
        {
            let passing_count = passing_candidate_count(
                source_facts.clone(),
                candidates.clone(),
                predicate.clone(),
            );
            match passing_count.clone() {
                0 => outcome_rejected(find_witness_no_candidate_diagnostic(source_facts.clone())),
                1 => match only_passing_candidate(
                    source_facts.clone(),
                    candidates.clone(),
                    predicate.clone(),
                ) {
                    Outcome::Accepted { value: only, .. } => {
                        accepted_witness_result(only.clone(), candidates.clone(), predicate.clone())
                    }
                    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
                        diagnostics: r.clone(),
                    }),
                },
                _ => match (*multiplicity_policy.clone()).clone() {
                    MultiplicityPolicy::UniqueOnly => outcome_rejected(
                        find_witness_ambiguous_candidate_diagnostic(source_facts.clone()),
                    ),
                    MultiplicityPolicy::TargetSelection { policy: p, .. } => {
                        match (*p.clone()).clone() {
                            TargetSelectionPolicy::TargetDeclaredPriority {
                                priority: priority,
                                ..
                            } => resolve_selected_candidate(
                                source_facts.clone(),
                                candidates.clone(),
                                predicate.clone(),
                                priority.clone(),
                            ),
                            TargetSelectionPolicy::UserSelected {
                                selection: selection,
                                ..
                            } => resolve_selected_candidate(
                                source_facts.clone(),
                                candidates.clone(),
                                predicate.clone(),
                                selection.clone(),
                            ),
                        }
                    }
                },
            }
        }
    }
}

